import streamlit as st

from src import metrics as M
from src import state, ui

params = state.scope_params()
if not params[0] or not params[1]:
    ui.empty_state("Select at least one season and one competition type.")
    st.stop()
S = state.compute_scope(params)
bat, bowl = state.player_filter(S["bat"]), state.player_filter(S["bowl"])
if bat.empty and bowl.empty:
    ui.empty_state()
    st.stop()

st.caption(
    "Shortlists are generated by fixed, documented rules from the statistics in the current scope. "
    "They are evidence for selection discussions - the dataset does not tell us about fitness, availability or auction status, "
    "so no such claims are made."
)

recs = M.recommendations(bat, bowl, n=st.slider("Players per discipline", 3, 10, 5, key="rec_n"))
section = st.segmented_control("Shortlist", list(recs), default=list(recs)[0], key="rec_section") or list(recs)[0]
df = recs[section]

if df.empty:
    ui.empty_state("No players meet this shortlist's rule in the current scope.")
    st.stop()

for disc, grp in df.groupby("discipline", sort=False):
    st.markdown(f"##### {':material/sports_cricket:' if disc == 'Batting' else ':material/sports_baseball:'} {disc}")
    st.caption(f"Rule: {grp['why'].iat[0]}.")
    with st.container(horizontal=True, gap="small", key=f"rec-grid-{disc}"):
        for _, r in grp.iterrows():
            with st.container(border=True, width=340):
                with st.container(horizontal=True, vertical_alignment="center", gap="small"):
                    st.markdown(f"**{r['display_name']}**")
                    st.badge(r["status"], color="green" if r["eligible"] else "orange")
                st.caption(f"{r['team']} | {r['role']}" + (f" | {r['latest_ipl_squad']} (latest IPL squad)" if isinstance(r.get("latest_ipl_squad"), str) else ""))
                with st.container(horizontal=True, gap="small"):
                    st.metric("Score" if r["eligible"] else "Provisional", ui.fmt_num(r["score"]))
                    if disc == "Batting":
                        st.metric("Pressure SR", ui.fmt_num(r["p_sr"]))
                        st.metric("Balls", f"{int(r['p_balls'])}")
                    else:
                        st.metric("Pressure econ", ui.fmt_num(r["p_econ"], 2))
                        st.metric("Wkts", f"{int(r['p_wkts'])}")
                st.markdown(f":small[{r['evidence']}]")
                if st.button("Profile", key=f"rec_go_{section}_{disc}_{r['player_id']}", icon=":material/person_search:", type="tertiary"):
                    st.session_state.profile_player = int(r["player_id"])
                    st.switch_page("app_pages/player_profile.py")

export = df[["discipline", "display_name", "team", "role", "status", "score", "evidence", "why"]]
ui.download_csv(export, f"rr_recommendations_{section.split()[0].lower()}.csv", key="dl_rec")
